import type { SupplierFamily, SupplierPricelist } from './types'
import { LIWO_MARKET, LIWO_QUESTIONS } from './liwo-market'

const SUPPLIER = {
  name: 'Shenzhen Liwo Technology Co., Ltd.',
  contact: 'Sun Lianghui — TEL/WeChat: +86 189 2849 0395',
  priceListDate: '2026-09-02',
  receivedAt: '2026-11-26',
}

const SECU = 'Maison connectée' as const

interface Opts {
  cat?: string
  sub?: string
  img?: string
  gallery?: string[]
  /** Variantes couleur [libelle, image] — meme prix usine, images dediees */
  vars?: Array<[string, string]>
  corp?: boolean
  market?: string
  feats?: string[]
  desc?: string
}

function L(key: string, name: string, cny: number, pack: [number, number, number], o: Opts = {}): SupplierFamily {
  const [pcs, kg, m3] = pack
  return {
    key,
    name,
    category: (o.cat || SECU) as SupplierFamily['category'],
    subCategory: o.sub || 'Prises & interrupteurs connectés',
    corporate: o.corp,
    image: o.img || '',
    gallery: o.gallery,
    weightKg: Math.round((kg / pcs) * 100) / 100,
    volumeM3: Math.round((m3 / pcs) * 10000) / 10000,
    marketLike: o.market,
    variantGroup: o.vars && o.vars.length ? 'Couleur' : 'Modèle',
    variants: o.vars && o.vars.length ? o.vars.map(([label, img]) => [label, cny, pcs, img] as [string, number, number, string]) : [['Standard', cny, pcs, o.img]],
    description: o.desc || '',
    features: o.feats,
  }
}

